\begin{align}
\omega_i\omega_j &= \omega_j\omega_i, \\
\omega_i\omega_i^{-1}&=\omega_i^{-1}\omega_i = 1, \\
\omega_ix_j\omega_i^{-1} &= q^{\delta_{ij}}x_j, \\
\omega_iy_j\omega_i^{-1} &= q^{-\delta_{ij}}y_j,\\
y_i x_j &= x_j y_i, \quad i\neq j, \\
y_ix_i - q^{-1} x_i y_i&=\omega_i,  \\
y_ix_i - q x_iy_i &= \omega_i^{-1}
\end{align}

where $i,j\in\{1,2,\ldots,n+1\}$.
The last two relations are equivalent to the two relations

\begin{equation}
y_ix_i =
\frac{q\omega_i - (q\omega_i)^{-1}}{q-q^{-1}},\qquad
x_iy_i=
\frac{\omega_i - \omega_i^{-1}}{q-q^{-1}}
\end{equation}
